const fs = require('node:fs');
// Independent re-computation straight from raw u.item flags (true genre order)
const NAMES = ['unknown','Action','Adventure','Animation',\"Children's\",'Comedy','Crime','Documentary','Drama','Fantasy','Film-Noir','Horror','Musical','Mystery','Romance','Sci-Fi','Thriller','War','Western'];
const movies = fs.readFileSync('u.item','utf8').split('\n').filter(l=>l.trim()).map(l=>{
  const f = l.split('|');
  const flags = f.slice(5,24).map(Number); // 19 flags
  return { id:+f[0], title:f[1], v: flags.slice(1) }; // true 18 dims: drop 'unknown'
});
const cos = (a,b)=>{let d=0,na=0,nb=0;for(let i=0;i<18;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return (na&&nb)?d/(Math.sqrt(na)*Math.sqrt(nb)):0;};
const get = id => movies.find(m=>m.id===id);
const v = m => NAMES.map((n,i)=> m.v.includes(1) && m.v[i]===1 ? 1:0);
const vec = m => m.v.map(x=>x); // already 0/1
const top = (p, excl) => movies.filter(m=>!excl.has(m.id))
  .map(m=>({id:m.id,t:m.title,s:cos(p,vec(m))}))
  .sort((a,b)=>b.s-a.s||a.id-b.id).slice(0,5);
const avg = vs => NAMES.slice(1).map((_,i)=> vs.reduce((s,x)=>s+x[i],0)/vs.length);
console.log('true genres 50 :', NAMES.slice(1).filter((_,i)=>vec(get(50))[i]));
console.log('true genres 172:', NAMES.slice(1).filter((_,i)=>vec(get(172))[i]));
console.log('true genres 182:', NAMES.slice(1).filter((_,i)=>vec(get(182))[i]));
console.log('true genres 181:', NAMES.slice(1).filter((_,i)=>vec(get(181))[i]));
console.log('cos(50,172)=', cos(vec(get(50)),vec(get(172))).toFixed(6));
console.log('TOP single 50:'); top(vec(get(50)), new Set([50])).forEach(r=>console.log(' ', r.id, r.t, r.s.toFixed(6)));
const p = avg([50,172,182].map(id=>vec(get(id))));
console.log('TOP profile:'); top(p, new Set([50,172,182])).forEach(r=>console.log(' ', r.id, r.t, r.s.toFixed(6)));
